'use strict';
(() => {
const D=LocHire,main=document.querySelector('main'),dialog=document.querySelector('dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'₦'+Number(v||0).toLocaleString('en-NG',{maximumFractionDigits:2});
const at=v=>v?new Date(v).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'})+' WAT':'';
const icons={work:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m3-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.work}</svg>`;
const btn=(t,a,primary=false,attrs='')=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${a}" ${attrs}>${t}</button>`;
const field=(n,l,v='',type='text',attrs='')=>`<div class="field"><label for="f-${n}">${l}</label><input id="f-${n}" name="${n}" type="${type}" value="${esc(v)}" ${attrs}></div>`;
const textarea=(n,l,v='',required=true)=>`<div class="field"><label for="f-${n}">${l}</label><textarea id="f-${n}" name="${n}" maxlength="1500" ${required?'required':''}>${esc(v)}</textarea></div>`;
const select=(n,l,options,v='')=>`<div class="field"><label for="f-${n}">${l}</label><select id="f-${n}" name="${n}">${options.map(x=>{const [k,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(k)}" ${String(k)===String(v)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;
const check=(n,l,on=false)=>`<label class="check-field"><input name="${n}" type="checkbox" ${on?'checked':''}><span>${l}</span></label>`;
const multi=(n,l,values,chosen=[])=>`<fieldset class="multi"><legend>${l}</legend>${values.map(v=>`<label><input name="${n}" type="checkbox" value="${v}" ${chosen.includes(v)?'checked':''}><span>${v}</span></label>`).join('')}</fieldset>`;
const errorBox=()=>'<p id="form-error" role="alert" tabindex="-1"></p>';
const head=(t,p,action='')=>`<section class="page-top"><div><div class="eyebrow">Local people. Everyday work.</div><h1>${esc(t)}</h1><p>${esc(p)}</p></div>${action}</section>`;
const empty=(t,p,a='')=>`<div class="empty"><h3>${esc(t)}</h3><p>${esc(p)}</p>${a}</div>`;
const detail=items=>`<dl class="detail-grid">${items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'Not specified')}</dd></div>`).join('')}</dl>`;
const badge=s=>`<span class="badge">${esc(s)}</span>`;
let state={user:null,worker:null,employer:null,workers:[],employers:[],openings:[],engagements:[],reviews:[],blocks:[],notifications:[],payments:[],reports:[]},config={};
let role=localStorage.getItem('lochire-role')==='employer'?'employer':'worker',page='home',routeId='',q='',category='',city='',minimum='',sort='recent',radius='',locationPoint=null,loading=true,networkError='',syncing=false,authMode='login',pending=null;
const own=()=>role==='worker'?state.worker:state.employer;
const person=id=>[...state.workers,...state.employers,state.worker,state.employer].find(p=>p?.id===id);
const engagement=id=>state.engagements.find(g=>g.id===id);
const actor=g=>g.workerId===state.worker?.id?g.workerId:g.employerId===state.employer?.id?g.employerId:null;
const rating=id=>{const r=state.reviews.filter(r=>r.target===id);return {count:r.length,average:r.length?r.reduce((s,r)=>s+r.rating,0)/r.length:0};};
const ratings=id=>{const r=rating(id);return `<p class="worker-rating">${icon('star')} ${r.count?r.average.toFixed(1)+' / 5 · '+r.count+' '+(r.count===1?'review':'reviews'):'No reviews yet'}</p>`;};
const rate=(p,job=false)=>p.quote||p.flexible?'Discuss a quote':(job?money(p.min)+' – '+money(p.max):money(p.pay))+' / '+({Hourly:'hour',Daily:'day',Monthly:'month','Per task':'task'}[p.basis]||'discuss');
const pidAttr=id=>`data-id="${esc(id)}"`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),6000);}
function formError(t){const el=document.querySelector('#form-error');if(el){el.textContent=t;el.focus();}else toast(t);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{Accept:'application/json'}:{Accept:'application/json','Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(35000)});const d=await r.json().catch(()=>({error:'Unexpected service response.'}));if(!r.ok){const e=Error(d.error||'The request could not be completed.');e.status=r.status;throw e;}return d;}
const statePath=()=>locationPoint?'hiring/state?lat='+encodeURIComponent(locationPoint.lat)+'&lon='+encodeURIComponent(locationPoint.lon):'hiring/state';
async function refresh(draw=true){if(syncing)return;syncing=true;try{state=await api(statePath());networkError='';if(draw&&!dialog.open&&(!main.querySelector('form')||(page==='record'&&!main.querySelector('textarea')?.value.trim())))render();else navigation();}catch(e){networkError='Could not refresh LocHire. '+e.message;navigation();}finally{syncing=false;}}
async function change(path,body){const d=await api(path,body);if(d.version===4)state=d;else await refresh(false);return d;}
function navigation(){const tabs=role==='worker'?[['discover','Find work','work'],['engagements','My work','calendar'],['notifications','Inbox','mail'],['profile','My profile','user']]:[['discover','Workers','people'],['engagements','My work','calendar'],['notifications','Inbox','mail'],['profile','My profile','user']];document.querySelector('#nav').innerHTML=tabs.map(([p,t,i])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('');document.querySelector('#role-button').innerHTML=icon(role==='worker'?'work':'people')+(role==='worker'?'Find work':'Hire')+icon('arrow');document.querySelector('#account-button').innerHTML=icon('user')+`<span class="sr-only">${state.user?'Account':'Sign in'}</span>`;document.querySelector('#account-button').setAttribute('aria-label',state.user?'Account settings':'Sign in');const n=state.notifications.filter(n=>!n.read_at).length;document.querySelector('#notification-button').innerHTML=icon('mail')+`<span>${n||''}</span>`;const el=document.querySelector('#connection-status');el.hidden=!networkError;el.textContent=networkError;}
function go(p,id=''){if(dialog.open)dialog.close();page=p;routeId=id;const hash=p+(id?'/'+encodeURIComponent(id):'');if(location.hash.slice(1)!==hash)location.hash=hash;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function modal(title,description,body){document.querySelector('#dialog-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" type="button" data-action="close" aria-label="Close">${icon('close')}</button></div><p class="modal-desc">${esc(description)}</p>${body}`;if(!dialog.open)dialog.showModal();}
function requireAccount(next){if(state.user)return true;pending=next;auth();return false;}
function requireProfile(next){if(!requireAccount(next))return false;if(own())return true;toast('Create your '+role+' profile first.');go('edit-profile');return false;}
function auth(mode='login'){authMode=mode;const create=mode==='register',forgot=mode==='forgot';modal(create?'Create your LocHire account':forgot?'Reset your password':'Welcome back',create?'One account for finding work and hiring people.':forgot?'Request a password reset email.':'Sign in to continue your hiring and conversations.',`<form id="auth-form">${create?field('name','Your name','','text','required maxlength="70" autocomplete="name"')+field('phone','Nigerian phone number','','tel','required pattern="(0|\\+234)[0-9]{10}" autocomplete="tel"'):''}${field('email','Email address','','email','required maxlength="254" autocomplete="email"')}${!forgot?field('password',create?'Password (at least 10 characters)':'Password','','password',`required minlength="10" maxlength="200" autocomplete="${create?'new-password':'current-password'}"`):''}${create?check('termsConsent','I agree to the <a href="#guidelines" target="_blank" rel="noopener">terms</a> and <a href="#privacy" target="_blank" rel="noopener">privacy notice</a>.'):''}${errorBox()}<button type="submit" class="button primary">${create?'Create account':forgot?'Request reset email':'Sign in'}</button><div class="auth-links">${btn(create?'I already have an account':'Create account',create?'auth-login':'auth-register')}${!forgot?btn('Forgot password?','auth-forgot'):btn('Back to sign in','auth-login')}</div></form>`);}
function render(){navigation();if(loading){main.innerHTML=empty('Loading LocHire','Connecting to saved profiles and openings.');return;}const pages={home,discover,profile:profilePage,'edit-profile':profileForm,openings:openingsPage,'edit-opening':openingForm,person:personPage,worker:personPage,employer:personPage,opening:openingPage,engagements:engagementsPage,record:recordPage,notifications:notificationsPage,messages:notificationsPage,wallet:walletPage,account:accountPage,help:helpPage,privacy:privacyPage,guidelines:termsPage,admin:adminPage,reset:resetPage,verify:verifyPage};(pages[page]||home)();}
function home(){main.innerHTML=`<section class="hero"><div class="eyebrow">Work starts close to home</div><h1>Find local workers.<br>Find work near you.</h1><p>Hire someone for a task or find your next job. Start with what you need.</p><div class="start-options"><button class="start-card" data-action="find-work">${icon('work')}<strong>I’m looking for work</strong><span>Create a worker profile and browse jobs.</span><span class="start-link">Find work ${icon('arrow')}</span></button><button class="start-card" data-action="hire">${icon('people')}<strong>I want to hire someone</strong><span>Browse workers or post a job.</span><span class="start-link">Find a worker ${icon('arrow')}</span></button></div></section><section class="home-categories" aria-label="Popular services">${D.categories.slice(0,6).map(c=>`<button data-action="category" data-value="${esc(c)}">${icon('work')}<span>${esc(c)}</span></button>`).join('')}</section><section class="panel profile-entry"><h2>Create your profile</h2><p>Introduce yourself so the right people can find you.</p><div class="row-actions">${btn('Create worker profile','be-worker',true)}${btn('Create hirer profile','be-employer')}</div></section><section class="how-it-works"><h2>How it works</h2><ol><li><strong>Find a match</strong><span>Browse workers or jobs near you.</span></li><li><strong>Agree the details</strong><span>Confirm the work, price and date together.</span></li><li><strong>Work and pay</strong><span>Complete the job, track payment and leave a review.</span></li></ol></section>`;}

function discover(){const hiring=role==='employer';main.innerHTML=head(hiring?'Find a worker.':'Find work near you.',hiring?'Browse real worker profiles and start a conversation.':'Explore ongoing jobs and one-off tasks.',hiring?btn('Post a job','post',true):btn('Publish my profile','edit-profile',true))+`<div class="browse-toolbar"><label class="search">${icon('search')}<input id="discovery-search" aria-label="Search" placeholder="${hiring?'Try plumber, cook or cleaner':'Search jobs or tasks'}" value="${esc(q)}"></label></div><div class="live-filters">${select('search-category','Service',[['','All services'],...D.categories],category)}${field('search-city','City / area',city,'search','maxlength="90"')}${hiring?select('search-rating','Rating',[['','Any rating'],['3','3+ stars'],['4','4+ stars'],['5','5 stars']],minimum)+select('search-sort','Sort by',[['recent','Recent'],['rating','Highest rated'],['nearest','Nearest']],sort):''}</div>${hiring?`<section class="nearby-controls"><div class="row-actions">${btn(icon('pin')+(locationPoint?' Update location':' Use my location'),'locate')}${locationPoint?btn('Clear location','clear-location'):''}</div>${select('search-radius','Distance',[['','Any distance'],['1000','Within 1 km'],['5000','Within 5 km'],['10000','Within 10 km'],['30000','Within 30 km']],radius)}<p class="caption">${locationPoint?'Location ready. Distances are approximate.':'Location is optional. You can search by city or area.'}</p></section>`:''}<div id="discovery-list" aria-live="polite"></div>`;renderDiscovery();}
function renderDiscovery(){const el=document.querySelector('#discovery-list');if(!el)return;const aliases={plumber:'plumbing',cook:'cooking',cleaner:'cleaning',driver:'driving',electrician:'electrical work',carpenter:'carpentry'},term=aliases[D.norm(q)]||D.norm(q),hiring=role==='employer';let list=(hiring?state.workers.filter(p=>p.id!==state.worker?.id&&p.published!==false):state.openings.filter(o=>o.status==='Open'&&o.employerId!==state.employer?.id)).filter(p=>(!term||D.norm([p.name,p.title,p.occupation,p.category,p.speciality,...(p.skills||[])].join(' ')).includes(term))&&(!category||(p.occupation||p.category)===category)&&(!city||D.norm(p.city+' '+p.area+' '+(p.coverage||[]).join(' ')).includes(D.norm(city)))&&(!hiring||!minimum||rating(p.id).average>=Number(minimum))&&(!hiring||!radius||p.distance&&p.distance.metres<=Number(radius)));if(hiring&&sort==='rating')list.sort((a,b)=>rating(b.id).average-rating(a.id).average);if(hiring&&sort==='nearest')list.sort((a,b)=>(a.distance?.metres??Infinity)-(b.distance?.metres??Infinity));el.innerHTML=`<div class="section-heading"><h2>${list.length} ${hiring?'workers':'openings'}</h2><button class="text-button" data-action="refresh">Refresh</button></div>`+(list.length?`<div class="cards">${list.map(p=>hiring?workerCard(p):openingCard(p)).join('')}</div>`:empty(hiring?'New workers start here.':'New opportunities start here.',hiring?'No published workers match this search. Try another area or invite a worker to create a profile.':'No openings match this search. Publish your profile so hirers can find you.',btn('Create a work profile','be-worker',true)));}
function workerCard(p){return `<article class="card"><div class="card-top"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>${badge(p.acceptingBookings===false?'Unavailable':'Accepting enquiries')}</div><h3>${esc(p.name)}</h3><p>${esc(p.occupation)} · ${esc(p.speciality)}</p><p class="meta">${icon('pin')} ${esc(p.area)}, ${esc(p.city)}</p>${ratings(p.id)}${p.distance?`<p class="caption">Approx. ${(p.distance.metres/1000).toFixed(1)} km away</p>`:''}<p class="rate">${esc(rate(p))}</p><div class="card-bottom">${btn('View profile','view-person',false,pidAttr(p.id))}</div></article>`;}
function openingCard(o){return `<article class="card"><div class="card-top">${badge(o.type)}${icon('work')}</div><h3>${esc(o.title)}</h3><p>${esc(o.description.slice(0,160))}</p><p class="meta">${icon('pin')} ${esc(o.area)}, ${esc(o.city)}</p><p class="caption">${esc(person(o.employerId)?.name||'Local hirer')}</p><p class="rate">${esc(rate(o,true))}</p><div class="card-bottom">${btn('View opening','view-opening',false,pidAttr(o.id))}</div></article>`;}
function profilePage(){if(!state.user){main.innerHTML=head('Your work starts here.','Create an account to publish your profile and find people near you.')+empty('One account. Two ways to use LocHire.','Find work and hire someone with separate profiles.',btn('Create account','auth-register',true)+btn('Sign in','auth-login'));return;}const p=own();main.innerHTML=head(role==='worker'?'Your work profile.':'Your employer profile.','Keep your work details, availability and general area up to date.',btn(p?'Edit profile':'Create profile','edit-profile',true))+(p?`<section class="profile-overview"><span class="avatar">${esc(p.name[0])}</span><h2>${esc(p.name)}</h2><p>${esc(p.occupation||p.type)} · ${esc(p.area)}, ${esc(p.city)}</p>${badge(p.suspended?'Suspended pending review':p.published?'Published':'Hidden')}</section><div class="settings-menu">${role==='employer'?`<button data-page="openings">${icon('work')}<span>My job posts</span>${icon('arrow')}</button>`:''}<button data-action="view-person" ${pidAttr(p.id)}>${icon('user')}<span>View my public profile</span>${icon('arrow')}</button><button data-page="wallet">${icon('work')}<span>Earnings & payments<small>Bank account and payment history</small></span>${icon('arrow')}</button><button data-page="account">${icon('shield')}<span>Account settings</span>${icon('arrow')}</button></div>`:empty('Introduce yourself.','A short profile helps people understand what you offer.',btn('Create profile','edit-profile',true)))+(p&&role==='worker'?`<section class="panel"><h2>Nearby discovery</h2><p>Location sharing is optional. Public searches show approximate distance, never your exact coordinates.</p>${btn(p.coordinates?'Update location':'Share current location','share-location')}${p.coordinates?btn('Remove location','remove-location'):''}<p class="caption">${p.coordinates?'Last shared '+at(new Date(p.coordinates.at).toISOString())+'. Expires after 24 hours.':'No location shared.'}</p></section>`:'')+`<section class="panel"><h2>Blocked profiles</h2>${state.blocks.filter(b=>b.actor===p?.id).map(b=>`<p>Blocked profile ${btn('Unblock','unblock',false,pidAttr(b.target))}</p>`).join('')||'<p>No blocked profiles.</p>'}</section>`;}
function profileForm(){if(!state.user){main.innerHTML=empty('Sign in to create your profile.','Your profile is saved to your account.',btn('Sign in','auth-login',true));return;}const worker=role==='worker',p=own()||{name:state.user.name,city:'',area:'',occupation:'Domestic help',days:['Mon','Tue','Wed','Thu','Fri'],types:['Ongoing job','One-off task'],hoursStart:'08:00',hoursEnd:'17:00',start:D.today(),basis:'Monthly',accommodation:'Live-out',published:true,acceptingBookings:true,type:'Household'};main.innerHTML=head(worker?'Create your worker profile.':'Create your hirer profile.','Your account email and phone stay private.')+`<form id="profile-form" class="panel live-form"><h2>About you</h2><div class="two-fields">${field('name',worker?'Name':'Your name / household / business',p.name,'text','required maxlength="70"')}${field('city','City',p.city,'text','required maxlength="70"')}</div>${field('area','General area',p.area,'text','required maxlength="90"')}${worker?`<h2>Your skills</h2><div class="two-fields">${select('occupation','Main occupation',D.categories,p.occupation)}${field('speciality','Speciality',p.speciality,'text','required maxlength="100"')}</div>${field('skills','Skills (comma separated)',(p.skills||[]).join(', '),'text','maxlength="1500"')}${field('years','Years of experience',p.years||0,'number','min="0" max="60"')}${textarea('experience','Work experience',p.experience,false)}<h2>Availability</h2>${multi('types','Types of work',['Ongoing job','One-off task'],p.types)}${multi('days','Working days',D.days,p.days)}<div class="two-fields">${field('hoursStart','Start time (WAT)',p.hoursStart,'time','required')}${field('hoursEnd','End time (WAT)',p.hoursEnd,'time','required')}${field('start','Available from',p.start,'date','required')}${field('coverage','Other areas covered (comma separated)',(p.coverage||[]).join(', '))}</div>${check('travel','Willing to discuss travel',p.travel)}<h2>Expected pay</h2><div class="two-fields">${field('pay','Expected pay (₦)',p.pay||'','number','min="0" max="100000000" step="0.01"')}${select('basis','Payment basis',D.bases,p.basis)}</div>${check('flexible','Price depends on the task',p.flexible)}${select('accommodation','Live-in / live-out',['Live-in','Live-out','Either','Not applicable'],p.accommodation)}<details class="optional-details"><summary>Previous work and licence details (optional)</summary>${textarea('workExample','Previous work',p.workExample,false)}${field('licence','Driving licence information (if relevant)',p.licence||'','text','maxlength="200"')}</details>${check('published','Publish my profile',p.published!==false)}${check('acceptingBookings','Accepting work enquiries',p.acceptingBookings!==false)}`:`${select('type','Employer type',['Individual','Household','Business'],p.type)}${textarea('intro','A short introduction',p.intro)}${textarea('business','Business details (required for businesses)',p.business,false)}`}<p class="note">Describe your experience honestly. Identity, licences and references are not independently verified.</p>${errorBox()}<div class="row-actions"><button type="submit" class="button primary">Save profile</button>${btn('Cancel','profile')}</div></form>`;}
function openingsPage(){const list=state.openings.filter(o=>o.employerId===state.employer?.id);main.innerHTML=head('Your openings.','Post an ongoing role or one-off task.',btn('Post a job','post',true))+(list.length?`<div class="cards">${list.map(openingCard).join('')}</div>`:empty('What help do you need?','Add clear work details, a general area and your budget.',btn('Post a job','post',true)));}
function openingForm(){if(!state.user||!state.employer){main.innerHTML=empty('Create an employer profile first.','Introduce yourself before posting work.',btn('Create employer profile','be-employer',true));return;}const p=state.openings.find(o=>o.id===routeId)||{type:'Ongoing job',category:'Domestic help',city:state.employer.city,area:state.employer.area,basis:'Monthly',days:['Mon','Tue','Wed','Thu','Fri'],hoursStart:'09:00',hoursEnd:'17:00',start:D.today(),date:D.today(),accommodation:'Live-out'},task=p.type==='One-off task';main.innerHTML=head(p.id?'Edit opening.':'What help do you need?','Give people enough information to decide whether the work suits them.')+`<form id="opening-form" class="panel live-form" ${pidAttr(p.id||'')} data-request="${crypto.randomUUID()}">${select('type','Type of work',['Ongoing job','One-off task'],p.type)}${select('category','Service / occupation',D.categories,p.category)}${field('title','Opening title',p.title||'','text','required maxlength="100"')}${textarea('description','Work description',p.description||'')}<div class="two-fields">${field('city','City',p.city,'text','required maxlength="70"')}${field('area','General area',p.area,'text','required maxlength="90"')}</div>${field('postcode','Postcode (optional; shared after acceptance)',p.postcode||'','text','maxlength="30"')}<p class="caption">Manual postcodes are not verified. Keep street addresses out of public descriptions.</p><div class="two-fields">${field('min','Minimum pay / budget (₦)',p.min||'','number','min="0" max="100000000" step="0.01"')}${field('max','Maximum pay / budget (₦)',p.max||'','number','min="0" max="100000000" step="0.01"')}</div>${select('basis','Payment basis',D.bases,p.basis)}${check('quote','Request a quote',p.quote)}${field('skills','Required skills (comma separated)',(p.skills||[]).join(', '),'text','maxlength="1500"')}${field('years','Relevant experience requested (years)',p.years||0,'number','min="0" max="60"')}<div data-work-fields="ongoing" ${task?'hidden':''}>${multi('days','Working days',D.days,p.days||[])}<div class="two-fields">${field('hoursStart','Start time (WAT)',p.hoursStart||'','time')}${field('hoursEnd','End time (WAT)',p.hoursEnd||'','time')}</div>${field('start','Start date',p.start,'date',`min="${D.today()}"`)}</div><div data-work-fields="task" ${task?'':'hidden'}>${field('date','Preferred date',p.date||D.today(),'date',`min="${D.today()}"`)}${field('duration','Estimated duration',p.duration||'','text','maxlength="100"')}${field('materials','Materials / tools',p.materials||'','text','maxlength="300"')}</div>${select('accommodation','Accommodation',['Live-in','Live-out','Either','Not applicable'],p.accommodation)}${errorBox()}<button type="submit" class="button primary">Save opening</button> ${btn('Cancel','openings')}</form>`;}
function personPage(){const p=person(routeId);if(!p){main.innerHTML=empty('Profile unavailable.','This profile may be hidden or no longer available.',btn('Browse','discover'));return;}const worker=!!p.occupation,mine=[state.worker?.id,state.employer?.id].includes(p.id),rr=state.reviews.filter(r=>r.target===p.id);main.innerHTML=head(p.name,(p.occupation||p.type)+' · '+p.area+', '+p.city)+`<div class="profile-columns"><div><section class="panel"><h2>${worker?'What I can offer':'About this hirer'}</h2><p>${esc(worker?p.experience||p.speciality:p.intro)}</p>${worker?ratings(p.id)+detail([['Speciality',p.speciality],['Skills',p.skills.join(', ')],['Experience',p.years+' years, self-reported'],['Work types',p.types.join(', ')],['Days',p.days.join(', ')],['Hours',p.hoursStart+' – '+p.hoursEnd+' WAT'],['Available from',p.start],['Expected pay',rate(p)],['Areas covered',p.coverage.join(', ')],['Accommodation',p.accommodation]])+`<h3>Previous work</h3><p>${esc(p.workExample||'No example added.')}</p>`:`<p>${esc(p.business||'')}</p>`}</section><section class="panel"><h2>Reviews from completed work</h2>${rr.length?rr.map(r=>`<article class="review"><strong>${r.rating} / 5 · ${esc(person(r.author)?.name||'Participant')}</strong><p>${esc(r.text)}</p><span class="caption">${at(r.at)}</span></article>`).join(''):'<p>No reviews yet.</p>'}</section>${!worker?`<section class="panel"><h2>Openings</h2>${state.openings.filter(o=>o.employerId===p.id&&o.status==='Open').map(openingCard).join('')||'<p>No current openings.</p>'}</section>`:''}</div><aside><section class="panel"><h2>Before deciding</h2><p>Work details are self-reported. Agree the scope, pay and schedule together. Exchange private contact details in the conversation when you are comfortable.</p>${worker&&!mine?btn('Request work / invite','invite',true,`${pidAttr(p.id)} ${p.acceptingBookings===false?'disabled':''}`):mine?btn('Edit profile','edit-profile'):''}</section>${!mine?`<div class="safety-actions">${btn('Report profile','report',false,`${pidAttr(p.id)} data-kind="profile"`)}${btn('Block contact','block',false,pidAttr(p.id))}</div>`:''}</aside></div>`;}
function openingPage(){const o=state.openings.find(o=>o.id===routeId);if(!o){main.innerHTML=empty('Opening unavailable.','It may have been closed.',btn('Browse openings','discover'));return;}const p=person(o.employerId),mine=o.employerId===state.employer?.id;main.innerHTML=head(o.title,o.type+' · '+o.area+', '+o.city)+`<div class="profile-columns"><section class="panel">${badge(o.status)}<h2>Work to be done</h2><p>${esc(o.description)}</p>${detail([['Pay / budget',rate(o,true)],['Skills',o.skills.join(', ')],['Experience',o.years+' years requested'],['Start / date',o.type==='One-off task'?o.date:o.start],['Days',o.days.join(', ')],['Hours',o.hoursStart&&o.hoursStart+' – '+o.hoursEnd+' WAT'],['Duration',o.duration],['Materials',o.materials],['Accommodation',o.accommodation]])}${mine&&o.postcode?`<p class="caption">Private postcode: ${esc(o.postcode)} · Not verified</p>`:''}</section><aside><section class="panel"><h2>Meet the hirer</h2><h3>${esc(p?.name||'Local hirer')}</h3><p>${esc(p?.intro||'')}</p>${btn('View hirer','view-person',false,pidAttr(o.employerId))}</section><section class="panel"><h2>Discuss before deciding.</h2><p>Confirm the scope, schedule and pay together.</p>${mine?btn('Edit opening','edit-opening',false,pidAttr(o.id))+btn(o.status==='Open'?'Close opening':'Reopen opening','opening-status',false,pidAttr(o.id)):o.status==='Open'?btn('Express interest','apply',true,pidAttr(o.id)):''}</section>${btn('Report opening','report',false,`${pidAttr(o.id)} data-kind="opening"`)}</aside></div>`;}
function invite(id){role='employer';localStorage.setItem('lochire-role',role);navigation();if(!requireProfile(()=>invite(id)))return;const p=person(id),jobs=state.openings.filter(o=>o.employerId===own().id&&o.status==='Open');modal('Invite '+p.name,'Your request appears in the worker’s LocHire inbox.',`<form id="invite-form" data-worker="${esc(id)}" data-request="${crypto.randomUUID()}">${select('openingId','Invite to an opening',[['','Request a one-off booking'],...jobs.map(o=>[o.id,o.title])])}<div data-booking-fields>${textarea('description','Work needed','')}${field('date','Preferred date',D.today(),'date',`min="${D.today()}"`)}${field('duration','Estimated duration','','text','maxlength="100"')}${field('city','City',state.employer.city)}${field('area','General area',state.employer.area)}</div>${textarea('message','Message to the worker','Please let me know your availability and price for this work.')}${errorBox()}<button type="submit" class="button primary">Send invitation</button></form>`);}
function apply(id){role='worker';localStorage.setItem('lochire-role',role);navigation();if(!requireProfile(()=>apply(id)))return;modal('Express interest','Introduce yourself and ask questions about the work.',`<form id="apply-form" data-opening="${esc(id)}">${textarea('message','Your message','')}${errorBox()}<button type="submit" class="button primary">Send interest</button></form>`);}
function engagementsPage(){const list=state.engagements.filter(g=>[g.workerId,g.employerId].includes(own()?.id));main.innerHTML=head('My work.','Your conversations, active jobs and completed work.')+(state.user?list.length?`<div class="stack">${list.map(g=>`<button class="list-row" data-action="record" ${pidAttr(g.id)}><span><strong>${esc(g.title)}</strong><small>${esc(person(g.workerId===own().id?g.employerId:g.workerId)?.name||'Participant')} · ${esc(g.status)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:empty('Start a conversation.','Find suitable work or invite a worker.',btn('Browse','discover',true)):empty('Sign in to see your work.','Engagements are private to participants.',btn('Sign in','auth-login',true)));}
function recordPage(){const g=engagement(routeId);if(!g){main.innerHTML=empty('Engagement unavailable.','Sign in to the account participating in this work.',btn('Sign in','auth-login'));return;}const a=actor(g),other=g.workerId===a?g.employerId:g.workerId,closed=['Completed','Declined','Cancelled'].includes(g.status),payer=a===g.employerId,payments=state.payments.filter(p=>p.engagement_id===g.id);let actions='';const action=(label,op)=>btn(label,'eng-action',true,`${pidAttr(g.id)} data-op="${op}" data-revision="${g.revision}" data-version="${g.version}"`);if(g.status==='Pending'&&a!==g.initiator)actions=action('Accept invitation','accept')+action('Decline','decline');if(['Accepted','Confirmed'].includes(g.status))actions+=btn(g.terms?'Propose revised details':'Propose work details','terms',true,pidAttr(g.id));if(g.status==='Accepted'&&g.terms&&g.confirmations[a]!==g.version)actions+=action('Confirm version '+g.version,'confirm');if(g.status==='Confirmed'&&!g.completion[a])actions+=action('Mark my side completed','complete');if(!closed)actions+=action('Cancel engagement','cancel');if(g.status==='Completed'&&!state.reviews.some(r=>r.engagementId===g.id&&r.author===a))actions+=btn('Leave a review','review',true,pidAttr(g.id));main.innerHTML=head(g.title,'With '+(person(other)?.name||'a participant'))+`<div class="profile-columns"><div><section class="panel">${badge(g.status)}<h2>Conversation</h2><div class="message-thread">${g.messages.slice(-100).map(m=>`<article class="message ${m.actor===a?'own':''}"><strong>${esc(person(m.actor)?.name||'Participant')}</strong><p>${esc(m.text)}</p><small>${at(m.at)}</small></article>`).join('')}</div>${!closed?`<form id="message-form" ${pidAttr(g.id)}>${textarea('text','Write a message','')}${errorBox()}<button type="submit" class="button primary">Send message</button></form>`:''}</section><section class="panel"><h2>Online payments</h2>${(state.onlinePayments||[]).filter(p=>p.engagementId===g.id).map(onlineCard).join('')||'<p>No online payments for this work.</p>'}${payer&&['Confirmed','Completed'].includes(g.status)?btn('Pay online','pay-online',true,`${pidAttr(g.id)} ${(state.provider||config.payments)?.ready?'':'disabled'}`):''}<p class="caption">${(state.provider||config.payments)?.ready?'Paystack processes payment and bank settlement.':'Online payments are awaiting activation.'}</p></section><section class="panel"><h2>Cash & direct transfers</h2><p>Cash and bank transfers are made directly between participants. LocHire records their acknowledgements and does not move or hold the money.</p>${payments.map(p=>`<article class="payment-record"><strong>${money(p.amount/100)} · ${p.method==='cash'?'Cash':'Bank transfer'}</strong><p>${esc(p.status==='reported'?'Reported by hirer, awaiting worker acknowledgement':p.status==='acknowledged'?'Acknowledged by worker':'Disputed by worker')}</p><p>${esc(p.note)}</p><span class="caption">${esc(p.id)} · ${at(p.created_at)}</span>${!payer&&p.status==='reported'?`<div class="row-actions">${btn('I received this payment','payment-ack',true,`${pidAttr(p.id)} data-eng="${g.id}" data-status="acknowledged"`)}${btn('I have not received it','payment-ack',false,`${pidAttr(p.id)} data-eng="${g.id}" data-status="disputed"`)}</div>`:''}</article>`).join('')||'<p>No payment recorded.</p>'}${payer&&['Confirmed','Completed'].includes(g.status)?btn('Record payment sent','record-payment',false,pidAttr(g.id)):''}</section></div><aside><section class="panel"><h2>Agreed work details</h2>${g.terms?detail([['Version',g.version],['Scope',g.terms.scope],['Pay',money(g.terms.pay)+' / '+g.terms.basis],['Schedule',g.terms.schedule],['Start',g.terms.start],['Completion',g.terms.completionDate],['Area',g.terms.area+', '+g.terms.city],['Payment method',g.terms.paymentMethod==='cash'?'Cash':'Direct bank transfer'],['Materials',g.terms.materials],['Accommodation',g.terms.accommodation]]):'<p>No work details proposed yet.</p>'}${g.postcode?`<p class="caption">Shared postcode: ${esc(g.postcode)} · Not verified</p>`:''}${g.terms?`<p class="caption">Worker: ${g.confirmations[g.workerId]===g.version?'confirmed':'awaiting confirmation'}<br>Hirer: ${g.confirmations[g.employerId]===g.version?'confirmed':'awaiting confirmation'}</p>`:''}${g.completion[a]&&g.status!=='Completed'?'<p>Your side is marked complete. Waiting for the other participant.</p>':''}<div class="record-actions">${actions}</div></section>${btn('Report a concern','report',false,`${pidAttr(g.id)} data-kind="engagement"`)}${btn('View participant','view-person',false,pidAttr(other))}</aside></div>`;}
function terms(id){const g=engagement(id),t=g.terms||{},o=state.openings.find(o=>o.id===g.openingId);modal('Agree the work details','Both participants must confirm this version. Revisions require fresh confirmations.',`<form id="terms-form" ${pidAttr(id)} data-revision="${g.revision}">${textarea('scope','Scope of work',t.scope||o?.description||'')}<div class="two-fields">${field('pay','Agreed pay (₦)',t.pay||'','number','required min="1" max="100000000" step="0.01"')}${select('basis','Payment basis',D.bases,t.basis||o?.basis||'Per task')}</div>${field('schedule','Schedule (WAT)',t.schedule||'','text','required maxlength="300"')}<div class="two-fields">${field('start','Start date',t.start||o?.start||D.today(),'date','required')}${field('completionDate','Completion date (if applicable)',t.completionDate||'','date')}${field('city','City',t.city||o?.city||'','text','required maxlength="70"')}${field('area','General area',t.area||o?.area||'','text','required maxlength="90"')}</div>${select('paymentMethod','Payment method',[['bank_transfer','Direct bank transfer'],['cash','Cash']],t.paymentMethod||'bank_transfer')}${field('materials','Materials / tools',t.materials||'','text','maxlength="300"')}${field('accommodation','Accommodation',t.accommodation||'','text','maxlength="100"')}${errorBox()}<button type="submit" class="button primary">Propose details</button></form>`);}
function report(id,kind='profile'){if(!requireAccount(()=>report(id,kind)))return;modal('Report a concern','Your report is saved privately for the LocHire owner to review. For immediate danger, contact local emergency services.',`<form id="report-form" ${pidAttr(id)} data-kind="${kind}">${select('reason','Reason',['Unwanted contact','Misleading information','Payment concern','Safety concern','Other'])}${textarea('details','What happened?','')}${errorBox()}<button type="submit" class="button primary">Submit report</button></form>`);}
function notificationsPage(){main.innerHTML=head('Your inbox.','Saved invitations, messages and work updates.',state.user?btn('Mark all read','read-all'):'')+(state.user?state.notifications.length?`<div class="stack">${state.notifications.map(n=>`<button class="list-row ${n.read_at?'':'unread'}" ${n.engagement_id?`data-action="record" ${pidAttr(n.engagement_id)}`:'data-page="help"'}><span><strong>${esc(n.title)}</strong><small>${at(n.created_at)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:empty('You’re up to date.','New invitations and messages will appear here.'):empty('Sign in to your inbox.','Your updates are private.',btn('Sign in','auth-login',true)));}
function onlineCard(p){const status={success:'Paid · Paystack verified',reversed:'Reversed by provider',pending:'Waiting for payment',initializing:'Checkout being checked',failed:'Payment failed',abandoned:'Payment not completed'};return `<article class="payment-record"><strong>${money(p.amount/100)} · ${esc(status[p.status]||p.status)}</strong><p>${esc(engagement(p.engagementId)?.title||'Work payment')} ${p.period==='once'?'':'· '+esc(p.period)}</p><p class="caption">${esc(p.reference)} · ${at(p.paidAt||p.createdAt)}</p>${p.status==='success'?`<p class="caption">Paystack handles bank settlement. This status confirms payment, not bank receipt.${p.fees!=null?' Provider fee: '+money(p.fees/100)+'.':''}</p>`:''}${btn('Check payment','verify-payment',false,`data-reference="${esc(p.reference)}"`)}</article>`;}
function walletPage(){
 if(!state.user){main.innerHTML=head('Payments.','Pay for work and receive earnings into your bank account.')+empty('Sign in to manage payments.','Your account and payment records stay private.',btn('Sign in','auth-login',true));return;}
 const worker=role==='worker',p=own(),provider=state.provider||config.payments||{},online=(state.onlinePayments||[]).filter(x=>worker?x.recipient===p?.id:x.payer===p?.id),records=state.payments.filter(x=>worker?x.recipient===p?.id:x.payer===p?.id),paid=online.filter(x=>x.status==='success').reduce((n,x)=>n+x.amount,0),direct=records.filter(x=>x.status==='acknowledged').reduce((n,x)=>n+x.amount,0),jobs=state.engagements.filter(g=>[g.workerId,g.employerId].includes(p?.id)&&['Confirmed','Completed'].includes(g.status));
 main.innerHTML=head(worker?'Your earnings.':'Payments.','Pay for agreed work. Keep track of each payment.')+`<div class="payment-summary"><section class="panel"><div class="eyebrow">Online payments confirmed</div><h2>${money(paid/100)}</h2><p>Verified by Paystack. Bank settlement is handled separately.</p></section><section class="panel"><div class="eyebrow">Direct payments received</div><h2>${money(direct/100)}</h2><p>Cash and transfers acknowledged by the worker.</p></section></div>${!provider.ready?`<div class="payment-status" role="status">${icon('shield')}<div><strong>Online payments are awaiting activation</strong><p>You can still agree cash or a direct bank transfer and record it below.</p></div></div>`:''}${worker?`<section class="panel"><h2>Receive money in your bank</h2>${state.bank?`<div class="bank-detail">${icon('shield')}<div><strong>${esc(state.bank.bankName)}</strong><p>${esc(state.bank.accountName)} · •••• ${esc(state.bank.last4)}</p></div></div>`:'<p>Connect a supported Nigerian bank account to receive online payments.</p>'}${btn(state.bank?'Change bank account':'Connect bank account','connect-bank',true,provider.ready?'':'disabled')}<p class="caption">Payments settle to your bank through Paystack. Provider fees are deducted from your settlement. No wallet top-up or withdrawal is needed.</p></section>`:`<section class="panel"><h2>Pay a worker</h2><p>Open agreed work below to pay with Paystack checkout. Available payment methods depend on Paystack and your account.</p></section>`}<section class="panel"><h2>${worker?'Your agreed work':'Choose work to pay for'}</h2>${!p?btn('Create your profile','edit-profile',true):jobs.length?jobs.map(g=>`<div class="payment-work"><div><strong>${esc(g.title)}</strong><p>${esc(person(worker?g.employerId:g.workerId)?.name||'Participant')} · ${money(g.terms?.pay||0)} / ${esc(g.terms?.basis||'discuss')}</p></div><div class="row-actions">${!worker?btn('Pay online','pay-online',true,`${pidAttr(g.id)} ${provider.ready?'':'disabled'}`)+btn('Record cash / transfer','record-payment',false,pidAttr(g.id)):btn('View payment records','record',false,pidAttr(g.id))}</div></div>`).join(''):empty('Agree a job first.','Both participants need to confirm the work details before payment.',btn('View my work','engagements'))}</section><section class="panel"><h2>Online payment history</h2>${online.length?online.map(onlineCard).join(''):'<p>No online payments yet.</p>'}</section><section class="panel"><h2>Cash & direct transfers</h2>${records.length?records.map(x=>`<button class="list-row" data-action="record" ${pidAttr(x.engagement_id)}><span><strong>${money(x.amount/100)} · ${esc({reported:'Awaiting worker confirmation',acknowledged:'Received · worker confirmed',disputed:'Disputed · receipt not confirmed'}[x.status])}</strong><small>${esc(engagement(x.engagement_id)?.title||'Work')} · ${x.method==='cash'?'Cash':'Bank transfer'} · ${at(x.created_at)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No cash or direct-transfer records yet.</p>'}</section>`;
}
async function connectBank(){if(!requireProfile(connectBank))return;modal('Connect your bank account','Choose the account where you want to receive payments.',empty('Loading banks','Getting the supported bank list.'));const r=await api('payments/banks');modal('Connect your bank account','Bank details are checked by Paystack and stay private.',`<form id="bank-resolve-form">${select('bankCode','Bank',[['','Choose your bank'],...r.banks.map(b=>[b.code,b.name])])}${field('accountNumber','Account number','','text','required inputmode="numeric" pattern="[0-9]{10}" minlength="10" maxlength="10" autocomplete="off"')}${check('consent','I agree to send these account details to Paystack for verification.')}${errorBox()}<button type="submit" class="button primary">Check account name</button></form>`);}
function payOnline(id){const g=engagement(id);if(!g)return toast('Work unavailable.');modal('Pay for '+g.title,'You will continue to Paystack’s secure checkout.',`<form id="online-payment-form" ${pidAttr(id)} data-version="${g.version}"><div class="checkout-amount">${money(g.terms.pay)}<span>Agreed ${esc(g.terms.basis.toLowerCase())} amount</span></div>${g.terms.basis!=='Per task'?field('period','What period are you paying for?','','text','required maxlength="60" placeholder="e.g. October 2026 or 12 October morning"'):''}<p>Paystack settles the payment to the worker’s connected bank account. Provider fees are deducted from the worker’s settlement.</p>${check('consent','I reviewed the amount and want to pay for this work.')}${errorBox()}<button type="submit" class="button primary">Continue to secure payment</button></form>`);}

function accountPage(){if(!state.user){main.innerHTML=empty('Sign in to your account.','Use the same account on any device.',btn('Sign in','auth-login',true)+btn('Create account','auth-register'))+`<div class="settings-menu"><button data-page="help">${icon('mail')}<span>Help & support</span>${icon('arrow')}</button><button data-page="privacy">${icon('shield')}<span>Privacy</span>${icon('arrow')}</button><button data-page="guidelines">${icon('work')}<span>Hiring guidance & terms</span>${icon('arrow')}</button></div>`;return;}main.innerHTML=head('Your account.','Manage sign-in and private contact details.')+`<section class="panel">${detail([['Name',state.user.name],['Email',state.user.email],['Phone',state.user.phone],['Email verification',state.user.emailVerified?'Verified':'Not verified']])}${!state.user.emailVerified?btn('Request verification email','verify-email'):''}<p class="caption">${state.emailReady?'Email delivery is connected.':'Verification and password-reset emails are awaiting email-provider setup.'}</p></section><form id="password-form" class="panel live-form"><h2>Change password</h2>${field('currentPassword','Current password','','password','required minlength="10" maxlength="200" autocomplete="current-password"')}${field('password','New password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${errorBox()}<button type="submit" class="button primary">Change password</button><p class="caption">This signs out sessions on all devices.</p></form><div class="settings-menu"><button data-page="help">${icon('mail')}<span>Help & support</span>${icon('arrow')}</button><button data-page="privacy">${icon('shield')}<span>Privacy</span>${icon('arrow')}</button><button data-page="guidelines">${icon('work')}<span>Hiring guidance & terms</span>${icon('arrow')}</button></div><div class="row-actions">${btn('Sign out','logout')}${state.admin?btn('Manage reports','admin'):''}</div>`;}
function helpPage(){main.innerHTML=head('Help & support.','Get help with work details, contact or a payment record.')+`<section class="panel"><h2>Report a concern</h2><p>Use Report on a profile, opening or engagement. Your report is saved privately for the LocHire owner to review.</p>${btn('Contact support','support',true)}</section><section class="panel"><h2>Payments</h2><p>Participants make cash and bank-transfer payments directly. An acknowledgement is not bank verification or payment insurance. Online payments use Paystack when activated; settlements go to the worker’s connected bank account.</p></section><section class="panel"><h2>Account security</h2><p>Use a unique password. Never share bank OTPs, PINs or passwords. Change your LocHire password in Account settings.</p></section>${state.reports?.length?`<section class="panel"><h2>Your reports</h2>${state.reports.map(r=>`<article class="review"><strong>${esc(r.reason)} · ${esc(r.status)}</strong><p>${esc(r.resolution||'Awaiting review.')}</p><span class="caption">${esc(r.id)}</span></article>`).join('')}</section>`:''}`;}
function privacyPage(){main.innerHTML=head('Your privacy.','How LocHire uses your information.')+`<section class="panel"><h2>Accounts and profiles</h2><p>LocHire stores accounts, hashed passwords, profiles, openings, conversations, reviews, payment acknowledgements and reports on its servers. An HttpOnly cookie keeps you signed in. Browser storage remembers only your selected role.</p><p>Your account email and phone stay private. Published profiles share your name, general area, work details and availability. Keep sensitive information out of public descriptions.</p><h2>Location and conversations</h2><p>Location sharing is optional. Exact snapshots stay private; searches return approximate distances for up to 24 hours. Removing your snapshot stops future location-based discovery. Conversations and payment declarations are visible only to participants. An opening’s postcode is shared with the worker after acceptance.</p><h2>Service providers and your choices</h2><p>Paystack processes online payments and bank settlement. Your bank details are sent to Paystack only when you connect an account. LocHire stores a private account name, bank name, masked number and provider account reference. Temporary verification details expire after 10 minutes. LocHire does not offer a stored-value wallet or escrow. Account email may be sent to an email provider when delivery is connected and you request recovery or verification. Hide your work profile, remove its location or sign out in Account. Request data access or account deletion through Help; some work records may need retention for dispute handling.</p></section>`;}
function termsPage(){main.innerHTML=head('Hiring guidance & terms.','Make clear agreements and treat each other respectfully.')+`<section class="panel"><h2>Agree the work</h2><p>LocHire connects workers with hirers. Participants assess suitability and agree scope, pay, schedule and safe working conditions. Information is self-reported unless explicitly verified. Both participants confirm the current work-details version, then completion before reviews become available.</p><h2>Safe payments and contact</h2><p>Do not send recruitment fees to get a job or share banking credentials. Pay through the secure checkout when available, or directly using the method you agreed. Paystack processing fees are deducted from online settlement to the worker. Bank receipt follows Paystack’s settlement schedule; payment success alone does not prove receipt. A payment acknowledgement is not a bank-verified transaction. LocHire currently offers no custody, escrow or payment insurance.</p><h2>Community and accounts</h2><p>Do not post misleading information, harass users or use discriminatory criteria. Block unwanted contact and report concerns. Profiles or openings may be hidden during review. Use accurate account details and a secure password. Use LocHire only if you are legally able to enter the work arrangement, and comply with applicable work rules.</p></section>`;}
async function adminPage(){if(!state.admin){main.innerHTML=empty('Administrator access required.','Sign in to the owner account.');return;}main.innerHTML=head('Manage reports.','Review concerns and record the action taken.')+empty('Loading reports','Fetching your private queue.');try{const data=await api('admin/reports');if(page!=='admin')return;main.innerHTML=head('Manage reports.','Review concerns and record the action taken.')+`<section class="panel"><p>${data.counts.accounts} accounts · ${data.counts.profiles} profiles · ${data.counts.openings} openings</p></section>`+(data.reports.map(r=>`<article class="panel"><h2>${esc(r.reason)}</h2>${badge(r.status)}<p>${esc(r.details)}</p><p class="caption">${esc(r.kind)} · ${esc(r.target)} · ${at(r.created_at)}</p>${r.status==='open'?`<form class="admin-report-form" ${pidAttr(r.id)}>${select('action','Action',[['resolve','Record resolution'],['hide_profile','Suspend reported profile'],['close_opening','Close reported opening']])}${textarea('resolution','Resolution / response','')}<button type="submit" class="button primary">Save resolution</button></form>`:`<p>${esc(r.resolution)}</p>`}</article>`).join('')||empty('No reports yet.','Submitted reports will appear here.'));}catch(e){toast(e.message);}}
function resetPage(){main.innerHTML=head('Choose a new password.','Reset links expire after one hour.')+`<form id="reset-form" class="panel live-form">${field('password','New password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${errorBox()}<button type="submit" class="button primary">Reset password</button></form>`;}
function verifyPage(){main.innerHTML=head('Verify your email.','Confirm the email associated with your account.')+`<form id="verify-form" class="panel">${errorBox()}<button type="submit" class="button primary">Verify email</button></form>`;}
async function selectRole(next){role=next;localStorage.setItem('lochire-role',role);if(dialog.open)dialog.close();navigation();if(state.user)await api('wallet/role',{role});}
function locate(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Location is unavailable on this device.'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,at:Date.now()}),e=>reject(Error(e.code===1?'Location permission declined. Search by city instead.':'Could not get your location. Try again or search by area.')),{enableHighAccuracy:true,timeout:10000,maximumAge:30000});});}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.page){go(b.dataset.page);return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;try{
  if(action==='close'){dialog.close();return;}if(action==='home'){go('home');return;}if(action==='role'){modal('One account. Two ways to use LocHire.','Choose how you want to use LocHire.',`<div class="modal-menu">${btn('Find work','role-worker',true)}${btn('Hire someone','role-employer',true)}</div>`);return;}if(action.startsWith('auth-')){auth(action.slice(5));return;}b.disabled=true;
  if(action==='role-worker'||action==='role-employer'){await selectRole(action==='role-worker'?'worker':'employer');render();}
  else if(action==='find-work'||action==='hire'){await selectRole(action==='hire'?'employer':'worker');go('discover');}
  else if(action==='category'){category=b.dataset.value;await selectRole('employer');go('discover');}
  else if(action==='be-worker'||action==='be-employer'){await selectRole(action==='be-worker'?'worker':'employer');if(requireAccount(()=>go('edit-profile')))go('edit-profile');}
  else if(action==='edit-profile'){if(requireAccount(()=>go('edit-profile')))go('edit-profile');}
  else if(['profile','openings','discover','account','admin','engagements','help','privacy','guidelines','wallet'].includes(action))go(action);
  else if(action==='post'){await selectRole('employer');if(requireProfile(()=>go('edit-opening')))go('edit-opening');}
  else if(action==='edit-opening')go('edit-opening',id);
  else if(action==='view-person')go('person',id);
  else if(action==='view-opening')go('opening',id);
  else if(action==='record')go('record',id);
  else if(action==='invite')invite(id);else if(action==='apply')apply(id);else if(action==='report')report(id,b.dataset.kind);else if(action==='support')report('support','support');
  else if(action==='refresh'){await refresh();render();}
  else if(action==='locate'){locationPoint=await locate();await refresh(false);sort='nearest';discover();toast('Location ready.');}
  else if(action==='clear-location'){locationPoint=null;radius='';sort='recent';await refresh(false);discover();}
  else if(action==='share-location'||action==='remove-location'){if(!state.worker)throw Error('Create a work profile first.');const p={...state.worker};if(action==='share-location')p.coordinates=await locate();else delete p.coordinates;await change('hiring/profiles/worker',p);render();toast(action==='share-location'?'Location shared.':'Location removed.');}
  else if(action==='opening-status'){const o=state.openings.find(o=>o.id===id);await change('hiring/openings/'+id,{action:'status',status:o.status==='Open'?'Closed':'Open',revision:o.revision});render();}
  else if(action==='eng-action'){const g=engagement(id),op=b.dataset.op;if(['cancel','complete','confirm'].includes(op))modal(op==='cancel'?'Cancel this engagement?':op==='complete'?'Mark your side complete?':'Confirm work details?',op==='confirm'?'Read the scope, pay and schedule. Your confirmation applies to version '+g.version+'.':op==='complete'?'The work becomes completed after both participants confirm.':'This closes the conversation and does not reverse any direct payment.',`${errorBox()}${btn('Go back','close')}${btn('Confirm','eng-final',true,`${pidAttr(id)} data-op="${op}" data-revision="${b.dataset.revision}" data-version="${b.dataset.version}"`)}`);else{await change('hiring/engagements/'+id+'/'+op,{revision:g.revision});render();}}
  else if(action==='eng-final'){await change('hiring/engagements/'+id+'/'+b.dataset.op,{revision:Number(b.dataset.revision),version:Number(b.dataset.version)});dialog.close();render();}
  else if(action==='terms')terms(id);
  else if(action==='review')modal('Review this completed work','Only participants in completed engagements can publish reviews.',`<form id="review-form" ${pidAttr(id)}>${select('rating','Rating',[[5,'5 - Excellent'],[4,'4 - Very good'],[3,'3 - Good'],[2,'2 - Fair'],[1,'1 - Poor']],5)}${textarea('text','Your experience','')}${errorBox()}<button type="submit" class="button primary">Publish review</button></form>`);
  else if(action==='block'||action==='unblock'){if(!requireProfile(()=>report(id)))return;await change('hiring/blocks',{role,target:id,blocked:action==='block'});go('profile');toast(action==='block'?'Contact blocked.':'Contact unblocked.');}
  else if(action==='read-all'){await change('hiring/notifications',{});render();}
  else if(action==='connect-bank')await connectBank();
  else if(action==='pay-online')payOnline(id);
  else if(action==='verify-payment'){const r=await api('payments/verify',{reference:b.dataset.reference});await refresh(false);render();toast(r.payment.status==='success'?'Payment confirmed by Paystack.':'Payment status: '+r.payment.status);}
  else if(action==='record-payment'){const g=engagement(id);modal('Record a payment you have sent','This records your declaration and asks the worker to acknowledge receipt. It does not initiate payment.',`<form id="payment-form" ${pidAttr(id)} data-request="${crypto.randomUUID()}">${field('amount','Amount paid (₦)',g.terms?.pay||'','number','required min="1" max="1000000" step="0.01"')}${select('method','Method',[['bank_transfer','Direct bank transfer'],['cash','Cash']],g.terms?.paymentMethod||'bank_transfer')}${field('note','Note (no bank credentials)','','text','maxlength="300"')}${errorBox()}<button type="submit" class="button primary">Record payment sent</button></form>`);}
  else if(action==='payment-ack'){await change('hiring/payments/'+id,{engagementId:b.dataset.eng,status:b.dataset.status});render();}
  else if(action==='logout'){await api('auth/logout',{});await refresh(false);go('home');toast('Signed out.');}
  else if(action==='verify-email'){const r=await api('auth/verification/request',{});toast(r.message);}
}catch(e){toast(e.message);if(e.status===409){await refresh(false);if(!dialog.open)render();}}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='discovery-search'){q=e.value;renderDiscovery();}if(e.name==='search-city'){city=e.value;renderDiscovery();}});
document.addEventListener('change',event=>{const e=event.target;if(e.name==='search-category')category=e.value;if(e.name==='search-rating')minimum=e.value;if(e.name==='search-sort')sort=e.value;if(e.name==='search-radius'){radius=e.value;if(radius&&!locationPoint)toast('Use my location for distance filters.');}if(e.name.startsWith('search-'))renderDiscovery();if(e.name==='type'&&e.form?.id==='opening-form'){document.querySelector('[data-work-fields="ongoing"]').hidden=e.value==='One-off task';document.querySelector('[data-work-fields="task"]').hidden=e.value!=='One-off task';}if(e.name==='openingId'&&e.form?.id==='invite-form'){const fields=e.form.querySelector('[data-booking-fields]');fields.hidden=!!e.value;fields.querySelectorAll('input,textarea').forEach(x=>x.disabled=!!e.value);}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();if(f.dataset.submitting==='true')return;f.dataset.submitting='true';const fd=new FormData(f),d=Object.fromEntries(fd),submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
  if(f.id==='auth-form'){if(authMode==='forgot'){const r=await api('auth/forgot',{email:d.email});formError(r.message);return;}if(authMode==='register'&&!fd.has('termsConsent'))throw Error('Agree to the terms and privacy notice first.');await api('auth/'+authMode,{...d,role:'both',termsConsent:fd.has('termsConsent')});await refresh(false);dialog.close();const next=pending;pending=null;if(next)next();else go('profile');toast(authMode==='register'?'Account created.':'Signed in.');}
  else if(f.id==='profile-form'){const p={...own(),...d,years:Number(d.years||0),pay:Number(d.pay||0)};if(role==='worker'){p.skills=D.list(d.skills);p.coverage=D.list(d.coverage);p.types=fd.getAll('types');p.days=fd.getAll('days');for(const k of ['travel','flexible','published','acceptingBookings'])p[k]=fd.has(k);}await change('hiring/profiles/'+role,p);go('profile');toast('Profile saved.');}
  else if(f.id==='opening-form'){const o={...d,requestId:f.dataset.request,min:Number(d.min||0),max:Number(d.max||0),years:Number(d.years||0),quote:fd.has('quote'),skills:D.list(d.skills),days:fd.getAll('days')};if(o.type==='One-off task')o.start=o.date;const previous=state.openings.find(o=>o.id===f.dataset.id);if(previous)o.revision=previous.revision;await change('hiring/openings'+(f.dataset.id?'/'+f.dataset.id:''),o);go('openings');toast('Opening saved.');}
  else if(f.id==='invite-form'){const body={role:'employer',workerId:f.dataset.worker,openingId:d.openingId,message:d.message,requestId:f.dataset.request};if(!d.openingId)body.booking={description:d.description,date:d.date,start:d.date,duration:d.duration,city:d.city,area:d.area};await change('hiring/engagements',body);dialog.close();go('engagements');toast('Invitation sent.');}
  else if(f.id==='apply-form'){await change('hiring/engagements',{role:'worker',openingId:f.dataset.opening,message:d.message});dialog.close();go('engagements');toast('Your interest was sent.');}
  else if(['message-form','terms-form','review-form'].includes(f.id)){const g=engagement(f.dataset.id),op=f.id==='message-form'?'message':f.id==='terms-form'?'terms':'review';await change('hiring/engagements/'+g.id+'/'+op,{...d,terms:op==='terms'?d:undefined,rating:d.rating?Number(d.rating):undefined,revision:op==='terms'?Number(f.dataset.revision):g.revision});if(dialog.open)dialog.close();render();toast(op==='message'?'Message sent.':op==='terms'?'Work details proposed.':'Review published.');}
  else if(f.id==='report-form'){const r=await api('hiring/reports',{target:f.dataset.id,kind:f.dataset.kind,reason:d.reason,details:d.details});await refresh(false);dialog.close();toast(r.message+' Reference '+r.reference);}
  else if(f.id==='bank-resolve-form'){const r=await api('payments/bank/resolve',{bankCode:d.bankCode,accountNumber:d.accountNumber,consent:fd.has('consent')});modal('Confirm your bank account','Check the account name carefully before saving.',`<form id="bank-save-form" data-token="${esc(r.token)}"><div class="bank-detail"><div><strong>${esc(r.accountName)}</strong><p>${esc(r.bankName)} · •••• ${esc(r.last4)}</p></div></div>${field('password','Your LocHire password','','password','required autocomplete="current-password"')}${check('consent','This is my account. I approve Paystack settlement to it.')}${errorBox()}<button type="submit" class="button primary">Save bank account</button></form>`);}
  else if(f.id==='bank-save-form'){await api('payments/bank/save',{token:f.dataset.token,password:d.password,consent:fd.has('consent')});await refresh(false);dialog.close();go('wallet');toast('Bank account connected.');}
  else if(f.id==='online-payment-form'){if(!fd.has('consent'))throw Error('Review and approve the payment first.');const r=await api('payments/checkout',{engagementId:f.dataset.id,version:Number(f.dataset.version),period:d.period});if(r.checkoutUrl){const u=new URL(r.checkoutUrl);if(u.protocol!=='https:'||u.hostname!=='checkout.paystack.com')throw Error('Checkout could not be validated.');window.location.assign(u.href);}else{await refresh(false);dialog.close();go('wallet');toast(r.message);}}
  else if(f.id==='payment-form'){await change('hiring/payments',{engagementId:f.dataset.id,requestId:f.dataset.request,amount:Math.round(Number(d.amount)*100),method:d.method,note:d.note});dialog.close();render();toast('Payment reported. Waiting for acknowledgement.');}
  else if(f.id==='password-form'){const r=await api('auth/password',d);await refresh(false);go('account');toast(r.message);}
  else if(f.id==='reset-form'||f.id==='verify-form'){const r=await api(f.id==='reset-form'?'auth/reset':'auth/verify',{...d,token:routeId});history.replaceState(null,'','#account');page='account';routeId='';await refresh(false);render();toast(r.message);}
  else if(f.classList.contains('admin-report-form')){await api('admin/reports',{...d,id:f.dataset.id});await refresh(false);adminPage();toast('Resolution saved.');}
}catch(e){formError(e.message);if(e.status===409)await refresh(false);}finally{delete f.dataset.submitting;if(submit?.isConnected)submit.disabled=false;}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
function hashRoute(){const [p,...parts]=location.hash.slice(1).split('/');page=p||'home';try{routeId=decodeURIComponent(parts.join('/'));}catch{routeId='';}render();}
window.addEventListener('hashchange',hashRoute);window.addEventListener('focus',()=>refresh());document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});window.addEventListener('pagehide',()=>{locationPoint=null;});setInterval(()=>{if(!document.hidden&&!dialog.open&&(!main.querySelector('form')||page==='record'))refresh();},30000);
async function boot(){const results=await Promise.allSettled([api('config'),api(statePath())]);if(results[0].status==='fulfilled')config=results[0].value;if(results[1].status==='fulfilled')state=results[1].value;else networkError='LocHire could not connect. '+results[1].reason.message;loading=false;hashRoute();const ref=new URL(location.href).searchParams.get('payment_reference');if(ref&&/^LHPS-[a-f0-9]{40}$/.test(ref)&&state.user){history.replaceState(null,'',location.pathname+'#wallet');try{const r=await api('payments/verify',{reference:ref});await refresh(false);go('wallet');toast(r.payment.status==='success'?'Payment confirmed by Paystack.':'Your payment is being checked.');}catch(e){go('wallet');toast(e.message);}}}
hashRoute();boot();
})();
